// PASO 1: Cargar el JSON
const data = await fetch('ciiu-riesgo-sst-colombia.json').then(r => r.json());

// PASO 2: Función de cálculo
function calcularPlanSST(codigoCiiu, numeroEmpleados) {
  const ciiu = data.clasificacion[codigoCiiu];
  if (!ciiu) return { error: 'CIIU no encontrado' };

  const riesgo = ciiu.riesgo;
  const esRiesgoAlto = (riesgo === 'IV' || riesgo === 'V');

  let capitulo, estandares, nombrePlan;

  if (esRiesgoAlto) {
    // Riesgo IV o V = SIEMPRE 61 estándares
    capitulo = 3;
    estandares = 61;
    nombrePlan = numeroEmpleados <= 50 ? 'Mediana Empresa' : 'Gran Empresa';
  } else {
    // Riesgo I, II, III = depende de empleados
    if (numeroEmpleados <= 10) {
      capitulo = 1;
      estandares = 7;
      nombrePlan = 'Microempresa';
    } else if (numeroEmpleados <= 50) {
      capitulo = 2;
      estandares = 21;
      nombrePlan = 'Pequeña Empresa';
    } else {
      capitulo = 3;
      estandares = 61;
      nombrePlan = numeroEmpleados <= 200 ? 'Mediana Empresa' : 'Gran Empresa';
    }
  }

  return {
    codigoCiiu,
    descripcion: ciiu.descripcion,
    numeroEmpleados,
    riesgo,
    esRiesgoAlto,
    capitulo,
    estandares,
    nombrePlan
  };
}

// PASO 3: Usar
console.log(calcularPlanSST('5511', 25)); // Hotel, 25 empleados
console.log(calcularPlanSST('4923', 5));  // Transporte carga, 5 empleados

