import { useState, useEffect } from 'react';

export function usePlanSST() {
  const [data, setData] = useState(null);

  useEffect(() => {
    fetch('/ciiu-riesgo-sst-colombia.json')
      .then(r => r.json())
      .then(setData);
  }, []);

  const calcular = (codigoCiiu, numeroEmpleados) => {
    if (!data) return null;
    const ciiu = data.clasificacion[codigoCiiu];
    if (!ciiu) return { error: 'CIIU no encontrado' };

    const riesgo = ciiu.riesgo;
    const esRiesgoAlto = riesgo === 'IV' || riesgo === 'V';

    let capitulo, estandares, nombrePlan;

    if (esRiesgoAlto) {
      capitulo = 3;
      estandares = 61;
      nombrePlan = numeroEmpleados <= 50 ? 'Mediana Empresa' : 'Gran Empresa';
    } else {
      if (numeroEmpleados <= 10) {
        capitulo = 1; estandares = 7; nombrePlan = 'Microempresa';
      } else if (numeroEmpleados <= 50) {
        capitulo = 2; estandares = 21; nombrePlan = 'Pequeña Empresa';
      } else {
        capitulo = 3; estandares = 61;
        nombrePlan = numeroEmpleados <= 200 ? 'Mediana Empresa' : 'Gran Empresa';
      }
    }

    return { codigoCiiu, descripcion: ciiu.descripcion, riesgo, esRiesgoAlto, capitulo, estandares, nombrePlan };
  };

  return { data, calcular, loading: !data };
}
